import java.lang.Class;
import java.lang.NoSuchMethodException;
import java.lang.String;
import java.lang.reflect.Modifier;
import java.lang.Exception;
import org.prairielearn.api.PlatformApiPrecheck;
import org.prairielearn.api.PlatformApiPrecheck.Api;
public class ApiContract {public static void check(Api api)throws Exception{api.method("Vehicle","getPassengers",int.class,Modifier.PUBLIC,0);api.method("Vehicle","getFuelcap",int.class,Modifier.PUBLIC,0);api.method("Vehicle","getMpg",int.class,Modifier.PUBLIC,0);api.method("Vehicle","range",int.class,Modifier.PUBLIC,0);api.method("Vehicle","setPassengers",void.class,Modifier.PUBLIC,0,int.class);api.method("Vehicle","setFuelcap",void.class,Modifier.PUBLIC,0,int.class);api.method("Vehicle","setMpg",void.class,Modifier.PUBLIC,0,int.class);api.method("Vehicle","fuelNeeded",double.class,Modifier.PUBLIC,0,int.class);api.method("Truck","getCargo",int.class,Modifier.PUBLIC,0);api.method("Truck","putCargo",void.class,Modifier.PUBLIC,0,int.class);constructor(api,"Vehicle",int.class,int.class,int.class);constructor(api,"Truck",int.class,int.class,int.class,int.class);api.compiles("Inputs","class Inputs {void use(){Vehicle x=new Vehicle(2,10,25);int p=x.getPassengers(),f=x.getFuelcap(),m=x.getMpg(),r=x.range();double fuel=x.fuelNeeded(1);x.setPassengers(0);x.setFuelcap(1);x.setMpg(1);Vehicle inherited=new Truck(2,10,25,1);Truck t=new Truck(2,10,25,1);int cargo=t.getCargo();t.putCargo(0);}}",true);}private static void constructor(Api api,String name,Class<?>...parameters)throws Exception{try{var c=api.type(name).getDeclaredConstructor(parameters);api.expect(Modifier.isPublic(c.getModifiers()),name+" public constructor",c.toGenericString());}catch(NoSuchMethodException missing){api.expect(false,name+" constructor",missing.toString());}}}
